import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.BDCokyix.js";const m=JSON.parse('{"title":"soma-agentd model-provider status","description":"","frontmatter":{},"headers":[],"relativePath":"development/agentd-models.md","filePath":"development/agentd-models.md","lastUpdated":1780254295000}'),s={name:"development/agentd-models.md"};function r(n,e,i,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="soma-agentd-model-provider-status" tabindex="-1"><code>soma-agentd</code> model-provider status <a class="header-anchor" href="#soma-agentd-model-provider-status" aria-label="Permalink to &quot;`soma-agentd` model-provider status&quot;">​</a></h1><p><code>soma-agentd</code> is no longer a standalone binary and no longer an OpenAI-compatible model provider or proxy.</p><p>It ships as a <strong>library crate</strong> (<code>backend/crates/agentd</code>, embedded by the Tauri host via the <code>desktop-agent</code> crate) that the <code>src-tauri</code> host loads in-process. Model/provider access for chat/embed/rerank goes through <code>desktop-agent</code>&#39;s OpenAI-compatible client; the provider configuration source of truth is the Tauri store, surfaced to the renderer through <code>@soma/sdk</code>.</p><h2 id="what-soma-agentd-does-now" tabindex="-1">What <code>soma-agentd</code> does now <a class="header-anchor" href="#what-soma-agentd-does-now" aria-label="Permalink to &quot;What `soma-agentd` does now&quot;">​</a></h2><ul><li>Library crate: <code>backend/crates/agentd</code> — exposes an in-process <code>AgentHandle</code> owned by the Tauri host&#39;s <code>desktop-agent</code> crate.</li><li>Local helpers retained: <ul><li><code>agentStatus</code></li><li><code>listModels</code> (returns an empty model list; the desktop side talks to Ollama / a remote endpoint instead)</li><li><code>resolveDrift</code> (Yjs update merge)</li></ul></li><li>The Unix-socket gRPC surface, the <code>--socket-path</code> / <code>SOMA_AGENTD_SOCKET</code> flags, and the persisted background-task store are gone (the desktop side keeps an in-memory background-task store in JS).</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The agent runtime shares the single embedded SQLite database with the daemon (its tables fold in from the former <code>agentd.db</code>). There are no <code>SOMA_AGENTD_*</code> environment variables.</p><p>The previous <code>SOMA_AGENTD_PROVIDER_BASE_URL</code>, <code>SOMA_AGENTD_PROVIDER_API_KEY</code>, <code>SOMA_AGENTD_DEFAULT_CHAT_MODEL</code>, <code>SOMA_AGENTD_DEFAULT_EMBED_MODEL</code>, and <code>SOMA_AGENTD_REQUEST_TIMEOUT_MS</code> knobs are no longer agentd options — model-provider configuration lives in the desktop config layer instead.</p>',8)])])}const g=o(s,[["render",r]]);export{m as __pageData,g as default};
